/**
 * The Sleepless Night
 * -------------------
 * The king cannot sleep, and the record of Mordecai's saved life is read aloud — the night turns. Stage: a sleepless king in a dim throne room, a scribe reading the chronicle; a rooster crowing in the dark; a single lamp turning the room.
 *
 * Palette 0x1a1024 → 0x060402 · light: dawn · hero: throne
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, column, throne, house, person } from './esther-kit.js';

const BG = 0x1a1024;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 890914643, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x140c1b });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x110a17 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -14, 0, -18, 1.0 + W.r() * 0.3, { mud: 0x060402 });
    house(W, group, 29, 0, -12, 0.8 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the throne */
    throne(W, group, 0, 0, 0, 1.5, { gold: 0x110a17 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.85, armR: [-0.2, 0.1], armL: [-0.2, -0.1], ry: 0.27, s: 1.14 });

    return W.finish();
}

export default { build };
